-- Nascita: van Sanity naar platform-CMS (snippet-slots uit het platform)
-- Draai op PROD (project kdhfpvjeriszteqhpgll). Idempotent.

-- 1. Zet nascita's CMS-provider op 'platform' zodat getHeroVariant/getCTAVariant uit
--    platform_cms_content lezen (bewerkbaar in de admin, geserveerd aan de snippet).
update tenant_settings set cms_provider = 'platform' where tenant_id = 'nascita';

-- 2. Migreer de huidige slot-varianten (1:1 uit de Sanity-seed) naar platform_cms_content,
--    zodat de live-site niet verandert. Daarna bewerk je ze in de Content-tab van nascita.
on conflict (tenant_id, variant_type, variant_key) do update set content = excluded.content;

-- 3. Verificatie
select variant_type, variant_key, left(content->>'title',48) as title
from platform_cms_content where tenant_id='nascita' order by variant_type, variant_key;
